  SWIG_InstallConstants(d,swig_const_table);
  
  SWIG_Python_SetConstant(d, "KTBN_ATEMPORAL",SWIG_From_int(static_cast< int >(gum::KTBN< double >::ATEMPORAL)));
  SWIG_Python_SetConstant(d, "KTBNInference_ATEMPORAL",SWIG_From_int(static_cast< int >(gum::KTBNInference< double >::ATEMPORAL)));
  SWIG_Python_SetConstant(d, "KTBNDatabaseGenerator_DiscretizedLabelMode_INTERVAL",SWIG_From_int(static_cast< int >(gum::learning::KTBNDatabaseGenerator< double >::DiscretizedLabelMode::INTERVAL)));
  SWIG_Python_SetConstant(d, "KTBNDatabaseGenerator_DiscretizedLabelMode_MEDIAN",SWIG_From_int(static_cast< int >(gum::learning::KTBNDatabaseGenerator< double >::DiscretizedLabelMode::MEDIAN)));
